Lemma ea_of (R : bvmap 5 word) (rs : bv 5) (imm : bv 12) (a : Z) :
  bv_unsigned (getr R rs) + bv_signed imm = a -> v_addi (getr R rs) (bv_signed imm) = Z_to_bv 64 a.
Proof.
